using System;

namespace ProjectEnchanter;

/// <summary>
/// Forward pass of the trained rune classifier (a small MLP: features → hidden
/// ReLU → softmax). Weights are generated by tools/train_rune_model.py and
/// compiled in via RuneModelWeights.g.cs.
/// </summary>
public static class RuneModel
{
    public static string[] OutputNames => RuneModelWeights.OutputNames;

    /// <summary>Predicts class probabilities for one feature vector.</summary>
    public static float[] Predict(float[] features)
    {
        if (features.Length != RuneModelWeights.InputSize)
        {
            throw new ArgumentException($"Expected {RuneModelWeights.InputSize} features, got {features.Length}.", nameof(features));
        }

        float[] standardized = new float[features.Length];
        for (int i = 0; i < features.Length; i++)
        {
            standardized[i] = (features[i] - RuneModelWeights.FeatureMean[i]) / RuneModelWeights.FeatureStd[i];
        }
        return Forward(standardized);
    }

    /// <summary>
    /// Predicts for both PCA mirror variants and averages the probabilities
    /// (the principal axis has no inherent sign).
    /// </summary>
    public static float[] PredictAveraged(float[] plus, float[] minus)
    {
        float[] a = Predict(plus);
        float[] b = Predict(minus);
        float[] averaged = new float[a.Length];
        for (int i = 0; i < a.Length; i++) averaged[i] = (a[i] + b[i]) * 0.5f;
        return averaged;
    }

    private static float[] Forward(float[] x)
    {
        int hiddenSize = RuneModelWeights.HiddenSize;
        int inputSize = RuneModelWeights.InputSize;
        int outputSize = RuneModelWeights.OutputSize;

        float[] hidden = new float[hiddenSize];
        for (int h = 0; h < hiddenSize; h++)
        {
            float sum = RuneModelWeights.B1[h];
            int row = h * inputSize;
            for (int i = 0; i < inputSize; i++)
            {
                sum += RuneModelWeights.W1[row + i] * x[i];
            }
            hidden[h] = MathF.Max(0f, sum); // ReLU
        }

        float[] logits = new float[outputSize];
        float max = float.MinValue;
        for (int o = 0; o < outputSize; o++)
        {
            float sum = RuneModelWeights.B2[o];
            int row = o * hiddenSize;
            for (int h = 0; h < hiddenSize; h++)
            {
                sum += RuneModelWeights.W2[row + h] * hidden[h];
            }
            logits[o] = sum;
            if (sum > max) max = sum;
        }

        float total = 0f;
        for (int o = 0; o < outputSize; o++)
        {
            logits[o] = MathF.Exp(logits[o] - max);
            total += logits[o];
        }
        for (int o = 0; o < outputSize; o++) logits[o] /= total;
        return logits;
    }
}
